package org.example.controller;

import javafx.fxml.FXML;
import javafx.fxml.FXMLLoader;
import javafx.scene.Parent;
import javafx.scene.Scene;
import javafx.scene.control.Button;
import javafx.scene.control.Label;
import javafx.scene.control.TextField;
import javafx.scene.layout.VBox;
import javafx.stage.Stage;
import org.example.model.Produit;
import org.example.service.ProduitService;

import java.io.IOException;

public class AccueilController {

    @FXML private TextField searchField;
    @FXML private Button searchButton;
    @FXML private Button profileButton;
    @FXML private VBox profileDropdown;

    private ProduitService produitService = new ProduitService();

    @FXML
    public void initialize() {
        // Add sample products
        addSampleProducts();
        loadProducts();
    }

    private void addSampleProducts() {
        produitService.add(new Produit(0, "Paracétamol", "Antalgique et antipyrétique", 5.50, 100, "Analgésiques", true));
        produitService.add(new Produit(0, "Ibuprofène", "Anti-inflammatoire non stéroïdien", 4.20, 80, "Anti-inflammatoires", true));
        produitService.add(new Produit(0, "Aspirine", "Antalgique et antiagrégant", 3.80, 120, "Analgésiques", true));
        produitService.add(new Produit(0, "Vitamine C", "Supplément vitaminique", 8.90, 50, "Vitamines", true));
    }

    @FXML
    private void handleSearch() {
        String query = searchField.getText();
        if (!query.isEmpty()) {
            var results = produitService.search(query);
            displayProducts(results);
        } else {
            loadProducts();
        }
    }

    private void loadProducts() {
        var produits = produitService.getAll();
        displayProducts(produits);
    }

    private void displayProducts(java.util.List<Produit> produits) {
        profileDropdown.getChildren().clear();
        for (Produit p : produits) {
            VBox productCard = new VBox(10);
            productCard.setStyle("-fx-background-color: white; -fx-padding: 20; -fx-background-radius: 15; -fx-effect: dropshadow(three-pass-box, rgba(0,0,0,0.1), 10, 0, 0, 5); -fx-alignment: center-left;");
            productCard.getStyleClass().add("card");
            productCard.getStyleClass().add("card-hover");

            Label nameLabel = new Label(p.getNom());
            nameLabel.setStyle("-fx-font-weight: bold; -fx-font-size: 18px; -fx-text-fill: #1E1E1E;");

            Label descLabel = new Label(p.getDescription());
            descLabel.setStyle("-fx-text-fill: #6B7280; -fx-wrap-text: true;");

            Label priceLabel = new Label(p.getPrix() + " €");
            priceLabel.setStyle("-fx-font-weight: bold; -fx-font-size: 16px; -fx-text-fill: #145A44;");

            productCard.getChildren().addAll(nameLabel, descLabel, priceLabel);
            profileDropdown.getChildren().add(productCard);
        }
    }

    @FXML
    private void toggleProfileDropdown() {
        boolean isVisible = profileDropdown.isVisible();
        profileDropdown.setVisible(!isVisible);
        profileDropdown.setManaged(!isVisible);
    }

    @FXML
    private void goToDashboard() throws IOException {
        FXMLLoader loader = new FXMLLoader(getClass().getResource("/fxml/Dashboard.fxml"));
        Parent root = loader.load();
        Scene scene = new Scene(root, 1400, 900);
        scene.getStylesheets().add(getClass().getResource("/css/styles.css").toExternalForm());
        Stage stage = (Stage) profileButton.getScene().getWindow();
        stage.setScene(scene);
    }
}

package org.example.controller;

import javafx.fxml.FXML;
import javafx.fxml.FXMLLoader;
import javafx.scene.Parent;
import javafx.scene.Scene;
import javafx.scene.control.Button;
import javafx.scene.control.TextField;
import javafx.scene.layout.VBox;
import javafx.stage.Stage;

import java.io.IOException;

public class AccueilController {

    @FXML private TextField searchField;
    @FXML private Button searchButton;
    @FXML private Button profileButton;
    @FXML private VBox profileDropdown;

    @FXML
    public void initialize() {
        // Initialize
    }

    @FXML
    private void handleSearch() {
        String query = searchField.getText();
        if (!query.isEmpty()) {
            System.out.println("Searching for: " + query);
        }
    }

    @FXML
    private void toggleProfileDropdown() {
        boolean isVisible = profileDropdown.isVisible();
        profileDropdown.setVisible(!isVisible);
        profileDropdown.setManaged(!isVisible);
    }

    @FXML
    private void goToDashboard() throws IOException {
        FXMLLoader loader = new FXMLLoader(getClass().getResource("/fxml/Dashboard.fxml"));
        Parent root = loader.load();
        Scene scene = new Scene(root, 1400, 900);
        scene.getStylesheets().add(getClass().getResource("/css/styles.css").toExternalForm());
        Stage stage = (Stage) profileButton.getScene().getWindow();
        stage.setScene(scene);
    }
}

package org.example;

import javafx.application.Application;
import javafx.fxml.FXMLLoader;
import javafx.scene.Parent;
import javafx.scene.Scene;
import javafx.stage.Stage;

public class CuraVitaApp extends Application {

    @Override
    public void start(Stage primaryStage) throws Exception {
        FXMLLoader loader = new FXMLLoader(getClass().getResource("/fxml/Accueil.fxml"));
        Parent root = loader.load();
        Scene scene = new Scene(root, 1400, 900);
        scene.getStylesheets().add(getClass().getResource("/css/styles.css").toExternalForm());

        primaryStage.setTitle("CuraVita - Gestion de Pharmacie");
        primaryStage.setScene(scene);
        primaryStage.show();
    }

    public static void main(String[] args) {
        launch(args);
    }
}

package org.example;

import javafx.application.Application;
import javafx.fxml.FXMLLoader;
import javafx.scene.Parent;
import javafx.scene.Scene;
import javafx.stage.Stage;

public class CuraVitaApp extends Application {

    @Override
    public void start(Stage primaryStage) throws Exception {
        FXMLLoader loader = new FXMLLoader(getClass().getResource("/fxml/Accueil.fxml"));
        Parent root = loader.load();
        Scene scene = new Scene(root);
        scene.getStylesheets().add(getClass().getResource("/css/styles.css").toExternalForm());

        primaryStage.setTitle("CuraVita - Gestion de Pharmacie");
        primaryStage.setScene(scene);
        primaryStage.setFullScreen(true);
        primaryStage.setFullScreenExitHint("Press ESC to exit fullscreen");
        primaryStage.show();
    }

    public static void main(String[] args) {
        launch(args);
    }
}

/* CuraVita Styles */

/* Root Variables */
.root {
    -primary-color: #145A44;
    -secondary-color: #1F7A5C;
    -accent-color: #2ECC71;
    -sidebar-bg: #0F3D2E;
    -background: #F5F7F6;
    -card-bg: #FFFFFF;
    -text-primary: #1E1E1E;
    -text-secondary: #6B7280;
    -text-on-dark: #FFFFFF;
}

/* General */
.root {
    -fx-background-color: -background;
    -fx-font-family: "Segoe UI", sans-serif;
}

/* Container for centered content */
.container {
    -fx-max-width: 1200px;
    -fx-alignment: center;
    -fx-padding: 40px;
}

/* Navbar Container - Centered wrapper */
.navbar-container {
    -fx-padding: 20px 40px;
    -fx-alignment: center;
    -fx-background-color: -background;
}

/* Navbar - Main bar */
.navbar {
    -fx-background-color: -card-bg;
    -fx-background-radius: 30px;
    -fx-effect: dropshadow(three-pass-box, rgba(0,0,0,0.1), 10, 0, 0, 5);
    -fx-padding: 0 35px;
    -fx-pref-height: 70px;
    -fx-alignment: center;
    -fx-spacing: 0;
    -fx-pref-width: 90%;
}

.logo {
    -fx-text-fill: -primary-color;
    -fx-font-size: 22px;
    -fx-font-weight: bold;
    -fx-min-width: 120px;
}

.nav-item {
    -fx-background-color: transparent;
    -fx-text-fill: -text-primary;
    -fx-font-size: 15px;
    -fx-border-color: transparent;
    -fx-cursor: hand;
    -fx-padding: 8px 14px;
    -fx-font-weight: 500;
    -fx-min-width: USE_PREF_SIZE;
}

.nav-item:hover {
    -fx-text-fill: -primary-color;
    -fx-background-color: rgba(20, 90, 68, 0.08);
    -fx-background-radius: 8px;
}

.search-field {
    -fx-pref-width: 220px;
    -fx-pref-height: 38px;
    -fx-background-radius: 20px;
    -fx-border-radius: 20px;
    -fx-padding: 8px 18px;
    -fx-font-size: 13px;
    -fx-border-color: #E5E7EB;
    -fx-border-width: 1px;
}

.nav-icon-button {
    -fx-background-color: -primary-color;
    -fx-text-fill: white;
    -fx-background-radius: 50%;
    -fx-min-width: 40px;
    -fx-min-height: 40px;
    -fx-pref-width: 40px;
    -fx-pref-height: 40px;
    -fx-cursor: hand;
    -fx-font-size: 16px;
    -fx-alignment: center;
}

.nav-icon-button:hover {
    -fx-background-color: -secondary-color;
    -fx-scale-x: 1.1;
    -fx-scale-y: 1.1;
}

.nav-icon-button:hover {
    -fx-background-color: -secondary-color;
    -fx-scale-x: 1.08;
    -fx-scale-y: 1.08;
}

/* Profile Dropdown */
.profile-dropdown {
    -fx-background-color: -card-bg;
    -fx-background-radius: 10px;
    -fx-effect: dropshadow(three-pass-box, rgba(0,0,0,0.15), 10, 0, 0, 4);
    -fx-padding: 8px 0;
    -fx-min-width: 150px;
    -fx-spacing: 0;
}

.dropdown-item {
    -fx-background-color: transparent;
    -fx-text-fill: -text-primary;
    -fx-font-size: 13px;
    -fx-padding: 12px 20px;
    -fx-alignment: center-left;
    -fx-cursor: hand;
    -fx-border-color: transparent;
}

.dropdown-item:hover {
    -fx-background-color: rgba(20, 90, 68, 0.1);
    -fx-text-fill: -primary-color;
}

/* Reusable Card */
.card {
    -fx-background-color: -card-bg;
    -fx-background-radius: 15px;
    -fx-effect: dropshadow(three-pass-box, rgba(0,0,0,0.1), 10, 0, 0, 5);
    -fx-padding: 30px;
}

/* Card Hover Effect */
.card-hover:hover {
    -fx-scale-x: 1.02;
    -fx-scale-y: 1.02;
    -fx-effect: dropshadow(three-pass-box, rgba(0,0,0,0.15), 15, 0, 0, 8);
    -fx-transition: all 0.3s ease;
}

/* Primary Button */
.button-primary {
    -fx-background-color: -accent-color;
    -fx-text-fill: white;
    -fx-background-radius: 10px;
    -fx-padding: 12px 24px;
    -fx-font-size: 14px;
    -fx-font-weight: bold;
    -fx-cursor: hand;
}

.button-primary:hover {
    -fx-background-color: -secondary-color;
}

/* Hero Section */
.hero-section {
    -fx-background-color: -primary-color;
    -fx-padding: 80px 40px;
    -fx-alignment: center;
}

.hero-title {
    -fx-text-fill: -text-on-dark;
    -fx-font-size: 48px;
    -fx-font-weight: bold;
    -fx-margin-bottom: 20px;
}

.hero-subtitle {
    -fx-text-fill: -text-on-dark;
    -fx-font-size: 24px;
    -fx-opacity: 0.9;
}

/* Cards Section */
.cards-section {
    -fx-padding: 40px 0;
}

/* Card Title and Description */
.card-title {
    -fx-font-size: 24px;
    -fx-font-weight: bold;
    -fx-text-fill: -text-primary;
    -fx-margin-bottom: 15px;
}

.card-description {
    -fx-text-fill: -text-secondary;
    -fx-font-size: 16px;
    -fx-text-alignment: center;
    -fx-wrap-text: true;
}

/* Products Container */
.products-container {
    -fx-padding: 20px 0;
}

/* Sidebar */
.sidebar {
    -fx-background-color: -sidebar-bg;
    -fx-padding: 30px 20px;
    -fx-pref-width: 220px;
}

.sidebar-logo {
    -fx-text-fill: -text-on-dark;
    -fx-font-size: 24px;
    -fx-font-weight: bold;
    -fx-padding: 0 20px;
}

.sidebar-item {
    -fx-background-color: transparent;
    -fx-text-fill: -text-on-dark;
    -fx-font-size: 16px;
    -fx-alignment: center-left;
    -fx-padding: 15px 20px;
    -fx-background-radius: 8px;
    -fx-pref-width: 180px;
    -fx-cursor: hand;
    -fx-transition: all 0.3s ease;
}

.sidebar-item:hover {
    -fx-background-color: -secondary-color;
    -fx-translate-x: 5px;
}

.sidebar-button-bottom {
    -fx-background-color: -accent-color;
    -fx-text-fill: white;
    -fx-background-radius: 30px;
    -fx-padding: 12px 24px;
    -fx-font-size: 16px;
    -fx-font-weight: bold;
    -fx-cursor: hand;
    -fx-pref-width: 180px;
    -fx-pref-height: 45px;
    -fx-margin: 0 20px 30px 20px;
    -fx-alignment: center;
}

.sidebar-button-bottom:hover {
    -fx-background-color: -secondary-color;
    -fx-scale-x: 1.02;
    -fx-scale-y: 1.02;
}

/* Main Content */
.main-scroll {
    -fx-background-color: transparent;
}

.main-content {
    -fx-padding: 40px;
    -fx-max-width: 1200px;
    -fx-alignment: center;
}

.main-title {
    -fx-font-size: 36px;
    -fx-font-weight: bold;
    -fx-text-fill: -text-primary;
    -fx-margin-bottom: 20px;
}

/* Stats Cards */
.stat-card {
    -fx-background-color: -card-bg;
    -fx-padding: 25px;
    -fx-background-radius: 12px;
    -fx-effect: dropshadow(three-pass-box, rgba(0,0,0,0.1), 8, 0, 0, 4);
    -fx-alignment: center;
    -fx-pref-width: 180px;
    -fx-pref-height: 100px;
}

.stat-label {
    -fx-text-fill: -text-secondary;
    -fx-font-size: 16px;
    -fx-margin-bottom: 10px;
}

.stat-value {
    -fx-text-fill: -text-primary;
    -fx-font-size: 42px;
    -fx-font-weight: bold;
}

/* Section Title */
.section-title {
    -fx-font-size: 22px;
    -fx-font-weight: bold;
    -fx-text-fill: -text-primary;
}

/* Activity Item */
.activity-item {
    -fx-text-fill: -text-secondary;
    -fx-font-size: 16px;
}

